<?php
error_reporting(E_ALL);
ini_set('display_errors', 1);
if (session_status() === PHP_SESSION_NONE) { session_start(); }
require_once '../config/database.php';
if (!isset($conn) || !$conn || $conn->connect_error) { die('Database connection failed.'); }
if (!isset($_SESSION['user_id']) || ($_SESSION['logged_in'] ?? false) !== true) { header('Location: ../login.php'); exit(); }

$user_id=(int)($_SESSION['user_id']??0); $user_name=trim(($_SESSION['first_name']??'Branch').' '.($_SESSION['last_name']??'Admin')); $user_role=$_SESSION['role']??'branch_admin'; $branch_id=(int)($_SESSION['branch_id']??0); $view_all_branches=(bool)($_SESSION['view_all_branches']??false);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function tableExists($conn,$t){$s=$conn->real_escape_string($t);$r=$conn->query("SHOW TABLES LIKE '{$s}'");return $r&&$r->num_rows>0;} function columnExists($conn,$t,$c){$t=$conn->real_escape_string($t);$c=$conn->real_escape_string($c);$r=$conn->query("SHOW COLUMNS FROM `{$t}` LIKE '{$c}'");return $r&&$r->num_rows>0;} function initials($n){$o='';foreach(preg_split('/\s+/',trim($n)) as $p){if($p!=='')$o.=strtoupper(substr($p,0,1));}return $o?substr($o,0,2):'BA';}
function createTables($conn){
$conn->query("CREATE TABLE IF NOT EXISTS `bank_transactions` (`transaction_id` int(11) NOT NULL AUTO_INCREMENT, `branch_id` int(11) NOT NULL DEFAULT 0, `transaction_type` enum('deposit','withdrawal') NOT NULL, `transaction_date` datetime NOT NULL, `reference_number` varchar(100) DEFAULT NULL, `bank_name` varchar(150) DEFAULT NULL, `description` text DEFAULT NULL, `amount` decimal(12,2) NOT NULL DEFAULT 0.00, `created_by` int(11) NOT NULL DEFAULT 0, `created_at` timestamp NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`transaction_id`), KEY `branch_id` (`branch_id`), KEY `transaction_type` (`transaction_type`), KEY `transaction_date` (`transaction_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");
$conn->query("CREATE TABLE IF NOT EXISTS `supplier_payments` (`supplier_payment_id` int(11) NOT NULL AUTO_INCREMENT, `po_id` int(11) NOT NULL, `supplier_id` int(11) DEFAULT NULL, `branch_id` int(11) NOT NULL DEFAULT 0, `payment_method` enum('cash','check','online_transfer') NOT NULL, `amount` decimal(12,2) NOT NULL DEFAULT 0.00, `payment_date` datetime NOT NULL, `reference_number` varchar(100) DEFAULT NULL, `check_date` date DEFAULT NULL, `bank_name` varchar(150) DEFAULT NULL, `bank_branch` varchar(150) DEFAULT NULL, `check_number` varchar(100) DEFAULT NULL, `cash_tendered` decimal(12,2) DEFAULT NULL, `cash_change` decimal(12,2) DEFAULT NULL, `status` enum('completed','pending','failed') DEFAULT 'completed', `bank_transaction_id` int(11) DEFAULT NULL, `created_by` int(11) NOT NULL DEFAULT 0, `created_at` timestamp NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`supplier_payment_id`), KEY `po_id` (`po_id`), KEY `supplier_id` (`supplier_id`), KEY `branch_id` (`branch_id`), KEY `bank_transaction_id` (`bank_transaction_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");
}
createTables($conn);
function getSupplierPayables($conn,$view_all,$branch_id){ if(!tableExists($conn,'purchase_orders'))return[]; $has_branch=columnExists($conn,'purchase_orders','branch_id'); $has_sid=columnExists($conn,'purchase_orders','supplier_id'); $join=($has_sid&&tableExists($conn,'suppliers'))?"LEFT JOIN suppliers s ON s.supplier_id=po.supplier_id":"LEFT JOIN suppliers s ON 1=0"; $sql="SELECT po.po_id, po.po_number, po.order_date, po.expected_delivery, po.total_amount, po.po_status, po.supplier_name, ".($has_sid?'po.supplier_id':'NULL AS supplier_id').", ".($has_branch?'po.branch_id':'0 AS branch_id').", COALESCE(NULLIF(TRIM(s.supplier_name),''),NULLIF(TRIM(po.supplier_name),''),'Unknown Supplier') display_supplier_name, COALESCE(SUM(sp.amount),0) paid_amount, (po.total_amount-COALESCE(SUM(sp.amount),0)) balance FROM purchase_orders po {$join} LEFT JOIN supplier_payments sp ON sp.po_id=po.po_id AND sp.status='completed' WHERE po.po_status='received' AND po.total_amount>0"; if(!$view_all&&$branch_id>0&&$has_branch)$sql.=" AND po.branch_id=?"; $sql.=" GROUP BY po.po_id HAVING balance>0.009 ORDER BY po.order_date DESC, po.po_id DESC"; $rows=[];$st=$conn->prepare($sql); if($st){if(!$view_all&&$branch_id>0&&$has_branch)$st->bind_param('i',$branch_id);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();} return $rows; }
function getSupplierPayments($conn,$view_all,$branch_id){$sql="SELECT sp.*, po.po_number, po.total_amount, COALESCE(NULLIF(TRIM(s.supplier_name),''),NULLIF(TRIM(po.supplier_name),''),'Unknown Supplier') supplier_name, CONCAT(COALESCE(u.first_name,''), CASE WHEN u.last_name IS NOT NULL AND u.last_name<>'' THEN CONCAT(' ',u.last_name) ELSE '' END) encoded_by_name FROM supplier_payments sp LEFT JOIN purchase_orders po ON po.po_id=sp.po_id LEFT JOIN suppliers s ON s.supplier_id=sp.supplier_id LEFT JOIN users u ON u.user_id=sp.created_by WHERE 1=1"; if(!$view_all&&$branch_id>0)$sql.=" AND sp.branch_id=?"; $sql.=" ORDER BY sp.payment_date DESC, sp.supplier_payment_id DESC LIMIT 100"; $rows=[];$st=$conn->prepare($sql); if($st){if(!$view_all&&$branch_id>0)$st->bind_param('i',$branch_id);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();} return $rows;}
function getPayableByPoId($conn,$po_id,$view_all,$branch_id){foreach(getSupplierPayables($conn,$view_all,$branch_id) as $p){if((int)$p['po_id']===(int)$po_id)return$p;}return null;}
function suppliersWithPayables($payables){$m=[];foreach($payables as $p){$k=strtolower($p['display_supplier_name']);if(!isset($m[$k]))$m[$k]=['name'=>$p['display_supplier_name'],'balance'=>0,'count'=>0];$m[$k]['balance']+=(float)$p['balance'];$m[$k]['count']++;}uasort($m,function($a,$b){return strcasecmp($a['name'],$b['name']);});return$m;}

$flash_success=$_SESSION['success_message']??'';$flash_error=$_SESSION['error_message']??'';unset($_SESSION['success_message'],$_SESSION['error_message']);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='record_supplier_payment'){
 try{$po_id=(int)($_POST['po_id']??0);$method=trim($_POST['payment_method']??'');$amount=(float)($_POST['amount']??0);$paydate=date('Y-m-d H:i:s',strtotime($_POST['payment_date']??'now'));if($po_id<=0)throw new Exception('Invalid payable selected.');if(!in_array($method,['cash','check','online_transfer'],true))throw new Exception('Invalid payment method.');if($amount<=0)throw new Exception('Payment amount must be greater than zero.');$payable=getPayableByPoId($conn,$po_id,$view_all_branches,$branch_id);if(!$payable)throw new Exception('Supplier payable not found or already fully paid.');if($amount>(float)$payable['balance']+0.009)throw new Exception('Payment amount cannot exceed payable balance.');
 $ref=null;$check_date=null;$bank=null;$bank_branch=null;$check_number=null;$cash_tendered=null;$cash_change=null;if($method==='cash'){$cash_tendered=(float)($_POST['cash_tendered']??0);if($cash_tendered<$amount)throw new Exception('Tendered amount is less than payment amount.');$cash_change=$cash_tendered-$amount;$bank=trim($_POST['cash_bank_name']??'Cash on Hand');}elseif($method==='check'){$check_date=trim($_POST['check_date']??'');$bank=trim($_POST['bank_name']??'');$bank_branch=trim($_POST['bank_branch']??'');$check_number=trim($_POST['check_number']??'');$ref=$check_number;if($check_date===''||$bank===''||$bank_branch===''||$check_number==='')throw new Exception('All check details are required.');}else{$ref=trim($_POST['reference_number']??'');$bank=trim($_POST['bank_wallet']??'');if($ref===''||$bank==='')throw new Exception('Reference number and Bank/Wallet are required.');}
 $bid=(!$view_all_branches&&$branch_id>0)?$branch_id:(int)($payable['branch_id']??0);$sid=(int)($payable['supplier_id']??0);$desc='Supplier payment - '.$payable['display_supplier_name'].' / '.$payable['po_number'];$conn->begin_transaction();$bt=$conn->prepare("INSERT INTO bank_transactions (branch_id,transaction_type,transaction_date,reference_number,bank_name,description,amount,created_by) VALUES (?,'withdrawal',?,?,?,?,?,?)");$bt->bind_param('issssdi',$bid,$paydate,$ref,$bank,$desc,$amount,$user_id);if(!$bt->execute())throw new Exception('Failed to save bank withdrawal: '.$bt->error);$bank_tx=(int)$conn->insert_id;$bt->close();$sp=$conn->prepare("INSERT INTO supplier_payments (po_id,supplier_id,branch_id,payment_method,amount,payment_date,reference_number,check_date,bank_name,bank_branch,check_number,cash_tendered,cash_change,bank_transaction_id,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$sp->bind_param('iiisdssssssddii',$po_id,$sid,$bid,$method,$amount,$paydate,$ref,$check_date,$bank,$bank_branch,$check_number,$cash_tendered,$cash_change,$bank_tx,$user_id);if(!$sp->execute())throw new Exception('Failed to save supplier payment: '.$sp->error);$sp->close();$conn->commit();$_SESSION['success_message']='Supplier payment recorded successfully.';}catch(Exception $e){@$conn->rollback();$_SESSION['error_message']=$e->getMessage();}header('Location: suppliercollection.php');exit();}

$payables=getSupplierPayables($conn,$view_all_branches,$branch_id);$history=getSupplierPayments($conn,$view_all_branches,$branch_id);$suppliers=suppliersWithPayables($payables);$total_payable=0;foreach($payables as $p)$total_payable+=(float)$p['balance'];$total_paid=0;foreach($history as $h)$total_paid+=(float)$h['amount'];$preselected=(int)($_GET['po_id']??0);$user_initials=initials($user_name);
?>
