00}.btn-amgc-dark{background:#052A47;color:#fff;border:none;border-radius:10px;min-height:44px;font-weight:700}.nav-tabs .nav-link{font-weight:700;color:#052A47}.nav-tabs .nav-link.active{color:#047857}.navbar-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:1.5rem}.mobile-menu-btn{display:none;background:transparent;border:none;font-size:1.5rem;color:#052A47}.page-note{color:#6b7280;font-size:.86rem}.modal-header{background:linear-gradient(135deg,#052A47 0%,#047857 100%);color:#fff}.modal-header .btn-close{filter:invert(1)}@media(max-width:992px){.sidebar{transform:translateX(-100%)}.sidebar.active{transform:translateX(0)}.main-content{margin-left:0!important}.mobile-menu-btn{display:block}}</style></head><body><div id="appPage">
