="bi bi-people-fill"></i><span class="nav-text">Users</span></a></li></ul></div></div><div class="sidebar-footer"><div class="user-profile-sidebar"><div class="user-avatar-sidebar"><?php echo h($user_initials); ?></div><div class="user-details-sidebar"><span class="user-name-sidebar"><?php echo h($user_name); ?></span><span class="user-role-sidebar"><?php echo h(ucfirst($user_role)); ?></span></div></div><button class="logout-btn-sidebar" onclick="logout()"><i class="bi bi-box-arrow-right"></i><span class="logout-text">Logout</span></button></div></div>
