<div class="row g-3 mb-3"><div class="col-md-6 col-xl-3"><div class="stat-card-banking d-flex justify-content-between align-items-center"><div><div class="stat-label">Open Payables</div><div class="stat-value">₱<?php echo number_format($total_payable,2); ?></div><div class="page-note"><?php echo count($payables); ?> received PO(s)</div></div><div class="stat-icon"><i class="bi bi-building"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card-banking d-flex justify-content-between align-items-center"><div><div class="stat-label">Suppliers</div><div class="stat-value"><?php echo count($suppliers); ?></div><div class="page-note">With unpaid received items</div></div><div class="stat-icon"><i class="bi bi-people"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card-banking d-flex justify-content-between align-items-center"><div><div class="stat-label">Supplier Payments</div><div class="stat-value">₱<?php echo number_format($total_paid,2); ?></div><div class="page-note">Latest history total</div></div><div class="stat-icon"><i class="bi bi-cash-coin"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card-banking d-flex justify-content-between align-items-center"><div><div class="stat-label">Source</div><div class="stat-value">Receive</div><div class="page-note">PO status received only</div></div><div class="stat-icon"><i class="bi bi-box-seam"></i></div></div></div></div>
<div class="section-card"><div class="section-header"><div><h5 class="mb-1">Supplier Collection / Payment</h5><div class="page-note">Para lang sa supplier na galing sa Receive Inventory.</div></div><a href="Withdrawal.php" class="btn btn-amgc-dark"><i class="bi bi-arrow-up-circle me-1"></i>Withdrawal Page</a></div><div class="section-body"><div class="row g-3 mb-3"><div class="col-md-5"><label class="form-label fw-bold">Filter Supplier</label><select class="form-select" id="supplierFilter"><option value="all">All Suppliers</option><?php foreach($suppliers as $s):?><option value="<?php echo h(strtolower($s['name'])); ?>"><?php echo h($s['name']); ?> — ₱<?php echo number_format($s['balance'],2); ?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Search PO / Supplier</label><input type="text" class="form-control" id="searchBox" placeholder="Search supplier or PO number"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-amgc-primary w-100" onclick="resetFilters()">Reset</button></div></div><ul class="nav nav-tabs mb-3"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#payablesPane" type="button">Payables</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#historyPane" type="button">Payment History</button></li></ul><div class="tab-content"><div class="tab-pane fade show active" id="payablesPane"><div class="table-responsive"><table class="table table-hover" id="payablesTable"><thead><tr><th>Supplier</th><th>PO Number</th><th>Received Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(empty($payables)):?><tr><td colspan="8" class="text-center py-4 text-muted">No supplier payables found.</td></tr><?php else: foreach($payables as $p):?><tr data-supplier="<?php echo h(strtolower($p['display_supplier_name'])); ?>" data-text="<?php echo h(strtolower($p['display_supplier_name'].' '.$p['po_number'])); ?>"><td><b><?php echo h($p['display_supplier_name']); ?></b></td><td><?php echo h($p['po_number']); ?></td><td><?php echo $p['order_date']?date('M d, Y',strtotime($p['order_date'])):'-'; ?></td><td class="amount-neutral">₱<?php echo number_format((float)$p['total_amount'],2); ?></td><td class="amount-positive">₱<?php echo number_format((float)$p['paid_amount'],2); ?></td><td class="amount-negative">₱<?php echo number_format((float)$p['balance'],2); ?></td><td><span class="badge rounded-pill badge-soft-yellow px-3 py-2">Payable</span></td><td><button type="button" class="btn btn-sm btn-amgc-primary" onclick='openPayModal(<?php echo json_encode(["po_id"=>(int)$p["po_id"],"po_number"=>$p["po_number"],"supplier_name"=>$p["display_supplier_name"],"balance"=>(float)$p["balance"]], JSON_HEX_APOS|JSON_HEX_QUOT); ?>)'>Pay</button></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="tab-pane fade" id="historyPane"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Date</th><th>Supplier</th><th>PO</th><th>Method</th><th>Bank / Wallet</th><th>Reference</th><th>Amount</th><th>Encoded By</th></tr></thead><tbody><?php if(empty($history)):?><tr><td colspan="8" class="text-center py-4 text-muted">No supplier payment history yet.</td></tr><?php else: foreach($history as $sp):?><tr><td><?php echo date('M d, Y h:i A',strtotime($sp['payment_date'])); ?></td><td><b><?php echo h($sp['supplier_name']); ?></b></td><td><?php echo h($sp['po_number']); ?></td><td><?php echo ucwords(str_replace('_',' ',h($sp['payment_method']))); ?></td><td><?php echo h($sp['bank_name']?:'-'); ?></td><td><?php echo h($sp['reference_number']?:'-'); ?></td><td class="amount-negative">₱<?php echo number_format((float)$sp['amount'],2); ?></td><td><?php echo h(trim($sp['encoded_by_name'])?:'Unknown User'); ?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div></div>
<div class="modal fade" id="payModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><form method="POST" class="modal-content"><input type="hidden" name="action" value="record_supplier_payment"><input type="hidden" name="po_id" id="pay_po_id"><div class="modal-header"><h5 class="modal-title">Record Supplier Payment</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-light border"><b>Supplier:</b> <span id="pay_supplier">-</span><br><b>PO:</b> <span id="pay_po">-</span><br><b>Balance:</b> <span class="amount-negative" id="pay_balance">₱0.00</span></div><div class="row g-3"><div class="col-md-6"><label class="form-label fw-bold">Payment Date</label><input type="datetime-local" name="payment_date" class="form-control" value="<?php echo date('Y-m-d\TH:i'); ?>" required></div><div class="col-md-6"><label class="form-label fw-bold">Payment Method</label><select name="payment_method" id="method" class="form-select" onchange="togglePaymentFields()" required><option value="cash">Cash</option><option value="check">Check</option><option value="online_transfer">Online Transfer</option></select></div><div class="col-md-6"><label class="form-label fw-bold">Amount</label><input type="number" step="0.01" min="0.01" name="amount" id="pay_amount" class="form-control" required></div><div class="col-md-6 cash-fields"><label class="form-label fw-bold">Cash Tendered</label><input type="number" step="0.01" min="0" name="cash_tendered" class="form-control"></div><div class="col-md-6 cash-fields"><label class="form-label fw-bold">Cash Source</label><input type="text" name="cash_bank_name" class="form-control" value="Cash on Hand"></div><div class="col-md-6 check-fields d-none"><label class="form-label fw-bold">Check Date</label><input type="date" name="check_date" class="form-control"></div><div class="col-md-6 check-fields d-none"><label class="form-label fw-bold">Bank Name</label><input type="text" name="bank_name" class="form-control"></div><div class="col-md-6 check-fields d-none"><label class="form-label fw-bold">Bank Branch</label><input type="text" name="bank_branch" class="form-control"></div><div class="col-md-6 check-fields d-none"><label class="form-label fw-bold">Check Number</label><input type="text" name="check_number" class="form-control"></div><div class="col-md-6 online-fields d-none"><label class="form-label fw-bold">Bank / Wallet</label><input type="text" name="bank_wallet" class="form-control"></div><div class="col-md-6 online-fields d-none"><label class="form-label fw-bold">Reference Number</label><input type="text" name="reference_number" class="form-control"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn btn-amgc-primary">Save Payment</button></div></form></div></div>
</div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js"></script><script>const preselectedPoId=<?php echo (int)$preselected; ?>;function peso(n){return '₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}function openPayModal(d){document.getElementById('pay_po_id').value=d.po_id;document.getElementById('pay_supplier').textContent=d.supplier_name;document.getElementById('pay_po').textContent=d.po_number;document.getElementById('pay_balance').textContent=peso(d.balance);document.getElementById('pay_amount').value=Number(d.balance).toFixed(2);document.querySelector('[name="cash_tendered"]').value=Number(d.balance).toFixed(2);togglePaymentFields();new bootstrap.Modal(document.getElementById('payModal')).show()}function togglePaymentFields(){const m=document.getElementById('method').value;document.querySelectorAll('.cash-fields').forEach(e=>e.classList.toggle('d-none',m!=='cash'));document.querySelectorAll('.check-fields').forEach(e=>e.classList.toggle('d-none',m!=='check'));document.querySelectorAll('.online-fields').forEach(e=>e.classList.toggle('d-none',m!=='online_transfer'))}function applyFilters(){const s=document.getElementById('supplierFilter').value,q=document.getElementById('searchBox').value.toLowerCase().trim();document.querySelectorAll('#payablesTable tbody tr[data-supplier]').forEach(tr=>{tr.style.display=((s==='all'||tr.dataset.supplier===s)&&(q===''||tr.dataset.text.includes(q)))?'':'none'})}function resetFilters(){document.getElementById('supplierFilter').value='all';document.getElementById('searchBox').value='';applyFilters()}function toggleSidebar(){const s=document.getElementById('sidebar');if(innerWidth<=992)s.classList.toggle('active');else{s.classList.toggle('collapsed');localStorage.setItem('sidebarCollapsed',s.classList.contains('collapsed'))}}function toggleSidebarDropdown(e,id){e.preventDefault();document.getElementById(id)?.classList.toggle('show')}function logout(){Swal.fire({title:'Are you sure?',text:'You will be logged out of the system',icon:'question',showCancelButton:true,confirmButtonColor:'#07d826',cancelButtonColor:'#6c757d',confirmButtonText:'Yes, logout'}).then(r=>{if(r.isConfirmed)location.href='../logout.php'})}document.addEventListener('DOMContentLoaded',()=>{document.getElementById('supplierFilter')?.addEventListener('change',applyFilters);document.getElementById('searchBox')?.addEventListener('input',applyFilters);document.getElementById('mobileMenuBtn')?.addEventListener('click',toggleSidebar);document.getElementById('desktopToggleBtn')?.addEventListener('click',toggleSidebar);if(preselectedPoId>0){[...document.querySelectorAll('button')].find(b=>b.getAttribute('onclick')?.includes('"po_id":'+preselectedPoId))?.click();}});</script></body></html>
